となるような$p$の範囲を求めよ．

関数$y=f(x)$ $(x\geqq0)$は次の条件\ding{"AC}，\ding{"AD}を満たしている．
\begin{description}
\item[\ding{"AC}]$f(x)$は微分可能で$f'(x)$は連続，かつ$f(x)>0$
\item[\ding{"AD}]正の定数$a$があって
$\displaystyle\int_0^x{(f(t))}^{-a}dt=\int_a^{f(x)}(e^{\displaystyle-\frac{t^2}{2}}+t^{-a})dt$
\end{description}
\begin{description}
\item[(1)]\ding{"AD}の等式の両辺を$x$について微分して得られる($y$の満たす)微分方程式を書け．また$f(0)$の値を求めよ．
\item[(2)]正の定数$b$，$c$があって次の不等式(イ)，(ロ)を満たしていることを示せ．
\begin{description}
\item[(イ)]$b \leqq f'(x) \leqq 1$
\item[(ロ)]$\displaystyle 0 \leqq f(x) \left( \frac{1}{f'(x)}-1 \right) \leqq c$
\end{description}
\item[(3)]$\displaystyle\lim_{x\to\infty}f'(x)$を求めよ．また$f'(x)$の最小値を求めよ．
\end{description}

$-1 \leqq x \leqq 1$で定義された関数$y=f(x)$はつぎの\ding{"AC}，\ding{"AD}を満たしている．
\begin{description}
\item[\ding{"AC}]$\sin f(x)=1-x^2$
\item[\ding{"AD}]$\displaystyle 0 \leqq f(x) \leqq \frac{\pi}{2}$
\end{description}
\begin{description}
\item[(1)]$x$を$y$の関数として表し，$y=f(x)$のグラフの概形をかけ．
\item[(2)]$y=f(x)$のグラフと$x$軸で囲まれた部分の面積を求めよ．
\end{description}

平面上で次の方程式\ding{"AC}を満たす点全体の集合を$C_1$，
\ding{"AD}を満たす点全体の集合を$C_2$とする．
\begin{description}
\item[\ding{"AC}]$x^2+y^2-1=0$
\item[\ding{"AD}]$10x^2+14xy+5y^2=1$
\end{description}
\begin{description}
\item[(1)]$a$，$b$，$c$，$d$は負でない整数で$ad-bc>0$を満たしている．
さらに$A=\begin{pmatrix} a & b \\ c & d \end{pmatrix}$の定める1次変換$f$が$C_2$を$C_1$に写している，
すなわち$f(C_2)=C_1$である．
このとき$a$，$b$，$c$，$d$を求めよ．
\item[(2)]$C_2$上の点で$x$座標，$y$座標とも整数であるものは何個あるか．
\end{description}

\begin{description}
\item[(1)]任意の定数$a$に対して$e^x \geqq e^a+(x-a)e^a$が成り立つことを示せ．
\item[(2)]$\displaystyle\int_0^1e^{\sin\pi x}dx\geqq e^\frac{2}{\pi}$を示せ．
\end{description}

